INSERT INTO metric_definitions (metric_key, version, label, surface, unit, confidence, formula, session_basis, basis_label, grains, direction, comparison_mode, treatment, source_tables, effective_from, effective_to, change_note, created_at) VALUES
  ('cpm_trend', 1, 'CPM trend', 'creative', 'ratio', 'platform_reported', 'CPM in the later half of the window ÷ CPM in the earlier half − 1', NULL, 'Impressions', '["platform","campaign","adset","ad","format","angle"]', 'lower_better', 'drop_day', 'Rising CPM on a flat creative is the auction charging more for the same attention. The window split in two: the later half against the earlier one, the ad against itself. Both halves must clear the impression threshold or the change is not shown, because a fortnight of noise can invent any trend.', '["fact_ad_daily"]', '1970-01-03', NULL, 'v1: added so an ad can be read as improving or decaying, not only as a level.', '2026-09-12T00:00:00Z'),
  ('ctr_trend', 1, 'CTR trend', 'creative', 'ratio', 'platform_reported', 'outbound CTR in the later half of the window ÷ CTR in the earlier half − 1', NULL, 'Impressions', '["platform","campaign","adset","ad","format","angle"]', 'higher_better', 'drop_day', 'Falling CTR with rising frequency is the audience tiring of the creative. The window split in two: the later half against the earlier one, the ad against itself. Both halves must clear the impression threshold or the change is not shown, because a fortnight of noise can invent any trend.', '["fact_ad_daily"]', '1970-01-03', NULL, 'v1: added so an ad can be read as improving or decaying, not only as a level.', '2026-09-12T00:00:00Z');
